<script setup lang="ts">
import { ref, type Ref, computed, onMounted } from "vue";
import { useCalculatorStore } from "@/store/useCalculatorStore";
import { userAnimationInstance } from "@/store/useAnimationInstanceStore";
import { animate } from "animejs";

const calculatorStore = useCalculatorStore();
const animationInstanceStore = userAnimationInstance();

const animationChild: Ref<HTMLElement | null> = ref(null);

const iconColor = computed(() =>
  calculatorStore.$state.theme === "light" ? "#000" : "#fff",
);

function toggleCalculatorMode() {
  const toggleButtonRect =
    animationInstanceStore.$state.toggleButton!.getBoundingClientRect();
  const buttonAreaRect =
    animationInstanceStore.$state.buttonArea!.getBoundingClientRect();

  const startCover = document.createElement("div");

  startCover.style.position = "fixed";
  startCover.style.top = toggleButtonRect.top + "px";
  startCover.style.left = toggleButtonRect.left + "px";
  startCover.style.width = toggleButtonRect.width + "px";
  startCover.style.height = toggleButtonRect.height + "px";
  startCover.style.borderRadius = getComputedStyle(
    animationInstanceStore.$state.toggleButton!,
  ).getPropertyValue("border-radius");

  startCover.classList = "transition-cover shadow-xl";

  document.body.appendChild(startCover);

  const endCover = document.createElement("div");

  endCover.style.position = "fixed";
  endCover.style.top = buttonAreaRect.top + "px";
  endCover.style.left = buttonAreaRect.left + "px";
  endCover.style.width = buttonAreaRect.width + "px";
  endCover.style.height = buttonAreaRect.height + "px";
  endCover.style.borderRadius = getComputedStyle(
    animationInstanceStore.$state.buttonArea!,
  ).getPropertyValue("border-radius");
  endCover.classList = "transition-cover";

  document.body.appendChild(endCover);

  // toggle button to button area
  animate(startCover, {
    translateX: buttonAreaRect.left - toggleButtonRect.left,
    translateY: buttonAreaRect.top - toggleButtonRect.top,
    scaleX: buttonAreaRect.width / toggleButtonRect.width,
    scaleY: buttonAreaRect.height / toggleButtonRect.height,
    borderRadius: "5%",
    opacity: {
      from: 0.5,

      to: 1,
    },
    duration: 500,
    transformOrigin: "top left",
  });
  // button area to toggle button
  animate(endCover, {
    translateX: toggleButtonRect.left - buttonAreaRect.left,
    translateY: toggleButtonRect.top - buttonAreaRect.top,
    scaleX: toggleButtonRect.width / buttonAreaRect.width,
    scaleY: toggleButtonRect.height / buttonAreaRect.height,
    opacity: {
      from: 0,
      to: 1,
    },
    duration: 500,
    transformOrigin: "top left",
  });

  calculatorStore.toggleMode();
}

onMounted(() => {
  if (animationChild.value) {
    animationInstanceStore.setAnimationInstance(
      animationChild.value,
      "toggleButton",
    );
  }
});
</script>

<style scoped>
.icon {
  height: 100%;
}
</style>
